const { PR_BASE: base, PR_HEAD: head, PR_TITLE: title } = process.env
const isRelease = base?.startsWith('release/')
if (!['development', 'develop', 'beta', 'main'].includes(base) && !isRelease)
  throw new Error('Unsupported pull request target.')
if ((['beta', 'main'].includes(base) || isRelease) && process.env.PR_HEAD_REPO !== process.env.PR_BASE_REPO)
  throw new Error('Release promotions must originate in this repository.')
if (base === 'beta' && head !== 'development') throw new Error('Promote development into beta; do feature work in development.')
if (base === 'develop' && !['feature/', 'bugfix/', 'hotfix/', 'release/'].some(prefix => head?.startsWith(prefix))
  && head !== 'main')
  throw new Error('Target develop from feature/* or bugfix/*; use release/* for release integration.')
if (isRelease && !head?.startsWith('bugfix/'))
  throw new Error('Create release branches from develop; only focused bugfix/* branches may enter a release branch.')
if (base === 'main' && head !== 'beta' && !head?.startsWith('release/') && !head?.startsWith('hotfix/'))
  throw new Error('Promote an approved release/* branch to main, or use an explicit hotfix/* branch.')
if ((base === 'development' || base === 'develop' || isRelease || head?.startsWith('hotfix/'))
  && !/^(feat|fix|perf|docs|refactor|test|build|ci|chore|revert)(\([^)]+\))?!?: .{8,}$/.test(title ?? ''))
  throw new Error('Use a Conventional Commit PR title, for example: feat(library): add console-scoped verification')
console.log(`Promotion policy passed: ${head} -> ${base}`)
